package db

import "github.com/google/uuid"

// Prefixed-UUID primary keys — self-describing in logs and URLs (02).
// There is no task_ prefix: A2A task IDs are generated by the SDK's own
// in-memory task store, not by this package (see pkg/a2aserver).
const (
	AgentIDPrefix      = "agt_"
	CheckIDPrefix      = "chk_"
	ValidationIDPrefix = "val_"
	SnapshotIDPrefix   = "snap_"
)

// NewID returns a new prefixed-UUID identifier, e.g. "agt_<uuid>".
func NewID(prefix string) string {
	return prefix + uuid.NewString()
}
